    streak       integer          NOT NULL DEFAULT 0,
    throttled_at timestamptz,
    last_pause   interval         NOT NULL DEFAULT interval '0',
    updated_at   timestamptz      NOT NULL,
    PRIMARY KEY (budget, key)
);

