-- 7: monitoring

ALTER TABLE synclane.coverage
    ADD COLUMN IF NOT EXISTS completed_to timestamptz,
    ADD COLUMN IF NOT EXISTS completed_at timestamptz;

UPDATE synclane.coverage AS c
SET completed_to = d.completed_to, completed_at = d.completed_at
FROM (SELECT queue, owner, type, max(window_end) AS completed_to, max(completed_at) AS completed_at
      FROM synclane.jobs
      WHERE status = 'completed' AND mode IN ('initial', 'recurring')
      GROUP BY queue, owner, type) AS d
WHERE c.queue = d.queue AND c.owner = d.owner AND c.type = d.type AND c.completed_at IS NULL;

CREATE TABLE IF NOT EXISTS synclane.job_stats (
    queue     text        NOT NULL,
    type      text        NOT NULL,
    hour      timestamptz NOT NULL,
    completed integer     NOT NULL DEFAULT 0,
    records   bigint      NOT NULL DEFAULT 0,
    failures  integer     NOT NULL DEFAULT 0,
    abandoned integer     NOT NULL DEFAULT 0,
    PRIMARY KEY (queue, type, hour)
);

CREATE INDEX IF NOT EXISTS job_stats_hour ON synclane.job_stats (hour);

CREATE INDEX IF NOT EXISTS jobs_initial
    ON synclane.jobs (queue, owner, type) INCLUDE (status) WHERE mode = 'initial';

INSERT INTO synclane.job_stats (queue, type, hour, completed, records, failures, abandoned)
SELECT queue, type, date_trunc('hour', completed_at, 'UTC'),
       count(*) FILTER (WHERE status = 'completed'),
       coalesce(sum(processed_count) FILTER (WHERE status = 'completed'), 0),
       count(*) FILTER (WHERE status = 'abandoned'),
       count(*) FILTER (WHERE status = 'abandoned')
FROM synclane.jobs
WHERE status IN ('completed', 'abandoned') AND completed_at IS NOT NULL
GROUP BY queue, type, date_trunc('hour', completed_at, 'UTC')
ON CONFLICT (queue, type, hour) DO NOTHING;

INSERT INTO synclane.migrations (version, name) VALUES (7, 'monitoring') ON CONFLICT (version) DO NOTHING;

-- 8: change notifications

CREATE OR REPLACE FUNCTION synclane.announce_job() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM pg_notify('synclane_synclane', json_build_object(
        'id', NEW.id,
        'queue', left(NEW.queue, 200),
        'owner', left(NEW.owner, 500),
        'type', left(NEW.type, 200),
        'status', NEW.status,
        'at', NEW.updated_at)::text);
    RETURN NULL;
END
$$;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'jobs_announce_insert' AND tgrelid = 'synclane.jobs'::regclass) THEN
        CREATE TRIGGER jobs_announce_insert
            AFTER INSERT ON synclane.jobs
            FOR EACH ROW EXECUTE FUNCTION synclane.announce_job();
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'jobs_announce_status' AND tgrelid = 'synclane.jobs'::regclass) THEN
        CREATE TRIGGER jobs_announce_status
            AFTER UPDATE OF status ON synclane.jobs
            FOR EACH ROW WHEN (OLD.status IS DISTINCT FROM NEW.status)
            EXECUTE FUNCTION synclane.announce_job();
    END IF;
END
$$;

INSERT INTO synclane.migrations (version, name) VALUES (8, 'change notifications') ON CONFLICT (version) DO NOTHING;

