INSERT INTO synclane.owners (queue, owner, updated_at)
SELECT queue, owner, now() FROM synclane.coverage
UNION
SELECT DISTINCT queue, owner, now() FROM synclane.jobs
ON CONFLICT (queue, owner) DO NOTHING;

